<template><div class="badge-admin"><el-alert title="成就徽章按真实业务与内容核定结果授予。核实虚假邀请或内容后，将按关联记录撤回奖励。" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="获奖记录" name="awards"/><el-tab-pane label="颁发荣誉" name="grant"/><el-tab-pane label="获取规则" name="rules"/><el-tab-pane label="优质内容核定" name="content"/><el-tab-pane label="信用与违规" name="integrity"/><el-tab-pane label="意见箱核验" name="feedback"/><el-tab-pane label="操作记录" name="logs"/></el-tabs><el-table v-if="tab==='awards'" :data="data.awards?.rows||[]" v-loading="loading"><el-table-column prop="appUserId" label="会员ID" width="95"/><el-table-column prop="nickname" label="会员"/><el-table-column prop="name" label="徽章"/><el-table-column prop="sourceNote" label="获奖依据" min-width="220"/><el-table-column label="所属城市" min-width="140"><template #default="{row}"><span v-if="row.badgeCode==='city_builder'">{{ row.city || '待补录城市' }}</span><span v-else>{{ row.city || '—' }}</span></template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="awardedAt" label="获得时间" width="170"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.badgeCode==='city_builder'&&row.status==='active'" v-hasPermi="['kangaroo:memberlevel:edit']" link type="primary" @click="openCityEditor(row)">{{ row.city ? '修改城市' : '补录城市' }}</el-button><el-button v-if="row.sourceKey!=='automatic'&&row.status==='active'" v-hasPermi="['kangaroo:memberlevel:edit']" link type="danger" @click="revoking=row">撤销</el-button></template></el-table-column></el-table><el-pagination v-if="tab==='awards'" v-model:current-page="page" :total="data.awards?.total||0" :page-size="30" layout="prev,pager,next,total" @current-change="load"/>
<el-form v-if="tab==='grant'" label-position="top" class="form" @submit.prevent><el-form-item label="会员账号ID"><el-input-number v-model="grant.userId" :min="1" :precision="0"/></el-form-item><el-form-item label="荣誉徽章"><el-select v-model="grant.code"><el-option v-for="d in manual" :key="d.code" :label="d.name" :value="d.code"/></el-select></el-form-item><el-form-item v-if="grant.code==='city_youth'||grant.code==='city_builder'" label="城市（必填）"><el-input v-model="grant.city" maxlength="64" placeholder="填写城市字典中的城市或目的地"/></el-form-item><el-form-item label="任命 / 评选编号（同一编号不会重复颁发）"><el-input v-model="grant.sourceKey" maxlength="100" placeholder="例如 annual-2026-001"/></el-form-item><el-form-item label="获奖依据"><el-input v-model="grant.note" type="textarea" :rows="4" maxlength="500" placeholder="记录实际任命或评选依据，至少5字"/></el-form-item><el-button v-hasPermi="['kangaroo:memberlevel:edit']" type="primary" :loading="busy" @click="award">确认颁发</el-button></el-form>
<el-table v-if="tab==='rules'" :data="data.definitions||[]"><el-table-column prop="name" label="徽章" width="180"/><el-table-column prop="ruleText" label="获取条件" min-width="420"/><el-table-column label="核定方式" width="180"><template #default="{row}">{{ row.metric==='manual'?'平台核验颁发':'按有效业务记录核算' }}</template></el-table-column></el-table>
<BadgeModeration v-if="tab==='content'||tab==='integrity'" :key="tab" :mode="tab" @saved="load"/>
<el-table v-if="tab==='logs'" :data="data.log||[]"><el-table-column prop="appUserId" label="会员ID"/><el-table-column prop="actor" label="操作人"/><el-table-column prop="action" label="操作"/><el-table-column prop="note" label="依据" min-width="300"/><el-table-column prop="createTime" label="时间" width="180"/></el-table>
<el-table v-if="tab==='feedback'" :data="data.feedback||[]"><el-table-column prop="appUserId" label="会员ID" width="100"/><el-table-column prop="content" label="具体建议" min-width="280"/><el-table-column prop="status" label="状态"/><el-table-column label="核验" min-width="300"><template #default="{row}"><template v-if="row.status==='pending'"><el-input v-model="notes[row.feedbackId]" placeholder="填写核验依据（至少5字）"/><el-button v-hasPermi="['kangaroo:memberlevel:edit']" :disabled="busy" @click="reviewFeedback(row,true)">有效</el-button><el-button v-hasPermi="['kangaroo:memberlevel:edit']" :disabled="busy" @click="reviewFeedback(row,false)">无效</el-button></template><span v-else>{{ row.reviewNote }}</span></template></el-table-column></el-table>
<el-form v-if="revoking" class="form" label-position="top"><el-form-item :label="'撤销 '+revoking.name+' 的依据'"><el-input v-model="revokeNote" type="textarea" :rows="3" maxlength="500"/></el-form-item><el-button type="danger" :loading="busy" @click="revoke">确认撤销</el-button><el-button @click="revoking=null">取消</el-button></el-form>
<el-dialog :model-value="!!editingCity" title="城市共建人所属城市" width="520px" @close="editingCity=null">
  <el-alert v-if="editingCity&&!editingCity.city" title="这条历史徽章缺少城市，补录后可在对应城市页署名。" type="warning" :closable="false"/>
  <el-form label-position="top" class="form" @submit.prevent>
    <el-form-item label="所属城市"><el-input v-model="cityForm.city" maxlength="64" placeholder="填写城市字典中的城市或目的地"/></el-form-item>
    <el-form-item label="调整依据"><el-input v-model="cityForm.note" type="textarea" :rows="3" maxlength="360" show-word-limit placeholder="说明本次补录或调整的依据，5至360字"/></el-form-item>
  </el-form>
  <template #footer><el-button :disabled="busy" @click="editingCity=null">取消</el-button><el-button type="primary" :loading="busy" @click="saveCity">保存城市</el-button></template>
</el-dialog></div></template>
<script setup>
import BadgeModeration from './BadgeModeration.vue'
import {ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus'
const notes=ref({});const data=ref({}),tab=ref('awards'),page=ref(1),loading=ref(false),busy=ref(false),revoking=ref(null),revokeNote=ref(''),grant=ref({userId:undefined,code:'',city:'',sourceKey:'',note:''})
const editingCity=ref(null),cityForm=ref({city:'',note:''})
const manual=computed(()=>(data.value.definitions||[]).filter(d=>d.metric==='manual'))
async function load(){loading.value=true;try{data.value=(await request({url:'/kangaroo/governance/badges',params:{pageNum:page.value}})).data}finally{loading.value=false}}
async function send(url,body){busy.value=true;try{await request({url:'/kangaroo/governance/'+url,method:'post',data:body});ElMessage.success('已保存，小程序重新打开页面即可同步');await load();return true}finally{busy.value=false}}
async function award(){if(await send('badges',grant.value))tab.value='awards'}
function openCityEditor(row){editingCity.value=row;cityForm.value={city:row.city||'',note:''}}
async function saveCity(){
  if(!editingCity.value)return
  if(!cityForm.value.city.trim()||cityForm.value.note.trim().length<5||cityForm.value.note.trim().length>360){ElMessage.warning('请填写城市和5至360字的调整依据');return}
  if(await send('badges/'+editingCity.value.awardId+'/city',cityForm.value))editingCity.value=null
}
async function revoke(){if(await send('badges/'+revoking.value.awardId+'/revoke',{note:revokeNote.value})){revoking.value=null;revokeNote.value=''}}
async function reviewFeedback(row,valid){await send('feedback/'+row.feedbackId,{valid,note:notes.value[row.feedbackId]||''})}
onMounted(load)
</script><style scoped>.badge-admin{padding:16px 0}.form{max-width:700px;padding:20px 0}.el-pagination{margin-top:20px}</style>
